let historyStack = [];
let currentScenario = null;
let toastNotifier = null;

function render(html){ currentHtml = html; if(htmlNotifier) htmlNotifier(html); scrollTop(); }
function push(step){ historyStack.push(step); }
function back(){
  if(historyStack.length <= 1){ goHome(); return; }
  historyStack.pop();
  const prev = historyStack[historyStack.length-1];
  prev.fn(...prev.args);
}
function nav(name, ...args){
  const fn = registry[name];
  if(typeof fn !== 'function') return;
  push({fn,args});
  fn(...args);
}
function footer(){
  return '';
}
function copyText(text){
  navigator.clipboard.writeText(text);
  if(toastNotifier) toastNotifier('Texto copiado.');
  else alert('Texto copiado.');
}
function copyDecoded(value){ copyText(decodeURIComponent(value)); }
function speechBox(text,label='Frase empática sugerida'){
  const encoded=encodeURIComponent(text);
  return `<div class="speech-box"><div class="speech-head"><div class="speech-title">💬 ${label}</div><button class="speech-copy" data-click="copyDecoded('${encoded}')">Copiar</button></div><p class="speech-text">“${text}”</p></div>`;
}
function goHome(){
  historyStack=[];
  currentScenario=null;
  render(`
    <div class="question">¿Qué servicio necesita revisar?</div>
    <div class="instruction">El asesor elige el tipo de atención y la guía muestra únicamente las validaciones que corresponden, incluyendo frases empáticas sugeridas dentro de cada proceso.</div>
    <div class="home-grid">
      <button class="scenario" data-click="internetHome()">
        <div class="emoji">🌐</div><h3>Internet</h3><p>Sin servicio, degradación, lentitud, intermitencia, un dispositivo y escalamiento.</p>
      </button>
      <button class="scenario" data-click="tvHome()">
        <div class="emoji">📺</div><h3>Televisión</h3><p>Diagnóstico general, d-BOX, TV análoga, FTTH, códigos de error, PIN y control remoto.</p>
      </button>
      <button class="scenario" data-click="billingHome()">
        <div class="emoji">🧾</div><h3>Boleta y cobros</h3><p>Variaciones de monto, cobros específicos, servicios fijos/móviles, copia de boleta y explicación al cliente.</p>
      </button>
    </div>
  `);
}

function internetHome(){
  historyStack=[];
  render(`
    <div class="breadcrumb">Inicio / Internet</div>
    
    <div class="question">¿Qué inconveniente reporta el cliente?</div>
    <div class="instruction">Selecciona el escenario principal para iniciar el diagnóstico guiado.</div>
    <div class="home-grid">
      <button class="scenario" data-click="start('sin_internet')"><div class="emoji">🚫</div><h3>Sin Internet</h3><p>Falla masiva, estado comercial, reset, tecnología y revisión técnica.</p></button>
      <button class="scenario" data-click="start('degradado')"><div class="emoji">🟠</div><h3>Internet degradado</h3><p>Estado domicilio, velocidad, posición, RSSI y cobertura.</p></button>
      <button class="scenario" data-click="start('intermitencia')"><div class="emoji">🔄</div><h3>Intermitencia</h3><p>Interferencias, prueba por cable y eventual visita.</p></button>
      <button class="scenario" data-click="start('lentitud')"><div class="emoji">🐢</div><h3>Lentitud</h3><p>Bandas WiFi y test de velocidad.</p></button>
      <button class="scenario" data-click="start('un_dispositivo')"><div class="emoji">📱</div><h3>Solo un dispositivo</h3><p>Celular, tablet, PC o notebook.</p></button>
      <button class="scenario" data-click="start('escalamiento')"><div class="emoji">⚠️</div><h3>Escalamiento</h3><p>Horario, registro y comunicación de plazo.</p></button>
    </div>${footer()}
  `);
}

function start(id){
  historyStack=[];
  currentScenario=id;
  const map={
    sin_internet: sinInternet1,
    degradado: degradado1,
    intermitencia: intermitencia1,
    lentitud: lentitud1,
    un_dispositivo: device1,
    escalamiento: escalamiento1
  };
  push({fn:map[id],args:[]});
  map[id]();
}

