  if(metodo==='vod') detail='VOD → carpeta → Pausa → Adelantar + 3 → obtener CPE ID → Last → comparar con cpeUnitAddress en BEC.';
  render(`<div class="breadcrumb">TV / d-BOX / Identificación</div><div class="question">Confirma el equipo correcto</div><div class="action-box"><b>Pasos</b>${detail}</div><div class="options"><button class="option" data-click="nav(tvConexionesDbox)"><strong>Equipo identificado →</strong><span>Revisar conexiones.</span></button></div>${footer()}`);
