function tvCaseList(tipo){
  const cfg = tvCases[tipo];
  if(!cfg){ tvCasuisticasHome(); return; }
  const buttons = cfg.cases.map((c,i) =>
    `<button class="quick-link tv-case-item" data-search="${c.toLowerCase()}" data-click="nav(tvCaseDetail,'${tipo}',${i})">${c}</button>`
  ).join('');
  render(`
    <div class="breadcrumb">TV / Casuísticas / ${cfg.title}</div>
    <div class="question">¿Qué problema presenta exactamente?</div>
    <div class="instruction">${cfg.subtitle} Identifica lo que el cliente ve o escucha antes de continuar.</div>
    <div style="margin:14px 0 16px;">
      <input id="tvCaseSearch" type="text" placeholder="Buscar problema o código..." 
        data-input="filterTvCases(this.value)"
        style="width:100%;padding:13px 15px;border:1px solid var(--border);border-radius:10px;font-size:15px;outline:none;">
    </div>
    <div class="quick-list" id="tvCaseList">${buttons}</div>
    ${speechBox('Para darle una indicación correcta, primero voy a identificar exactamente qué está ocurriendo en pantalla y revisar la casuística correspondiente. Así evitamos hacer pruebas que no apliquen a su caso.','Indagación antes de pruebas')}
    ${footer()}
  `);
}
function filterTvCases(value){
  const q=(value||'').toLowerCase().trim();
  document.querySelectorAll('.tv-case-item').forEach(el=>{
    el.style.display = el.dataset.search.includes(q) ? '' : 'none';
  });
}
function tvCaseDetail(tipo,index){
  const cfg=tvCases[tipo];
  const problema=cfg.cases[index];
  let extra='';
  if(tipo==='vod'){
    extra=`<div class="action-box"><b>Antes de buscar</b>Pregunta qué mensaje o código aparece y confirma el código exacto con el cliente.</div>`;
  } else if(tipo==='replay'){
    extra=`<div class="action-box"><b>Antes de buscar</b>Identifica exactamente qué ocurre y el código de error, si aparece.</div>`;
  } else {
    extra=`<div class="action-box"><b>Antes de buscar</b>Confirma qué está viendo el cliente en pantalla y que esta es la casuística correcta.</div>`;
  }
  render(`
    <div class="breadcrumb">TV / ${cfg.title} / ${problema}</div>
    <div class="question">${problema}</div>
    ${extra}
    <div class="result">
      <div class="result-head">Ruta indicada por el procedimiento</div>
      <div class="result-row"><div>Buscar en</div><div>${cfg.route}</div></div>
      <div class="result-row"><div>Acción</div><div>Seleccionar esta casuística y aplicar exactamente las instrucciones publicadas allí.</div></div>
      <div class="result-row"><div>Después</div><div>Validar el resultado con el cliente. Si se solucionó, cerrar y tipificar; si no, continuar con la derivación indicada en la publicación.</div></div>
    </div>
    <div class="action-box warning"><b>Importante</b>El procedimiento compartido enumera esta casuística, pero no contiene su paso a paso individual. La guía no agrega pruebas no documentadas.</div>
    ${speechBox('Gracias por explicarme lo que aparece en pantalla. Ya identifiqué la casuística que corresponde y voy a seguir las validaciones específicas para este escenario. Le iré indicando cada paso para que podamos revisar el servicio de forma ordenada.','Casuística identificada')}
    <div class="options">
      ${tipo==='analoga' ? `<button class="option" data-click="nav(tvAnalogStart)"><strong>📡 Volver a TV Análoga</strong><span>Revisar conexión, modelo o factibilidad.</span></button>` : ''}
      <button class="option" data-click="nav(tvCaseList,'${tipo}')"><strong>← Elegir otra casuística</strong><span>Volver al listado de ${cfg.title}.</span></button>
    </div>${footer()}
  `);
}


