const billingExplainerCauses = {
  fixed: [
    {id:'promo', label:'Cambio de promoción / proporcionales'},
    {id:'discount', label:'Eliminación o término de descuento'},
    {id:'sva', label:'Servicio adicional / Extensor WiFi'},
    {id:'assistance', label:'Asistencia VTR'},
    {id:'ipc', label:'Reajuste por IPC'},
    {id:'cut', label:'Corte y reposición'},
    {id:'premium', label:'Canal o Pack Premium'}
  ],
  mobile: [
    {id:'rental', label:'Equipo en arriendo'},
    {id:'cut', label:'Corte y reposición móvil'},
    {id:'longdistance', label:'Larga distancia'},
    {id:'proportional', label:'Cobro proporcional / cambio de plan'},
    {id:'noservice', label:'Días sin servicio / descuento Ley de Telecom.'},
    {id:'additional', label:'Servicio adicional'},
    {id:'minutes', label:'Consumo de minutos'}
  ]
};

function formatCLP(n){
  if(n===null || n===undefined || isNaN(n)) return '';
  const sign=n<0?'-':'';
  return sign+'$'+Math.abs(Math.round(n)).toString().replace(/\B(?=(\d{3})+(?!\d))/g,'.');
}
function parseCLP(v){
  if(!v) return null;
  const clean=String(v).replace(/[^\d-]/g,'');
  if(!clean || clean==='-') return null;
  return Number(clean);
}
function val(id){
  const el=document.getElementById(id);
  return el ? el.value.trim() : '';
}
function escText(s){
  return String(s||'').replace(/[&<>"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
}
function causeLabel(service,cause){
  const found=(billingExplainerCauses[service]||[]).find(x=>x.id===cause);
  return found ? found.label : '';
}
function updateBillingCauseOptions(selected=''){
  const service=document.getElementById('be_service')?.value || 'fixed';
  const select=document.getElementById('be_cause');
  if(!select) return;
  select.innerHTML=(billingExplainerCauses[service]||[]).map(x =>
    `<option value="${x.id}" ${x.id===selected?'selected':''}>${x.label}</option>`
  ).join('');
  updateBillingExtraFields();
}
function updateBillingExtraFields(){
  const service=document.getElementById('be_service')?.value || 'fixed';
  const cause=document.getElementById('be_cause')?.value || '';
  const box=document.getElementById('be_extra_fields');
  if(!box) return;
  let extra='';
  if(service==='fixed' && cause==='promo'){
    extra=`
      <div class="field"><label>Plan anterior (opcional)</label><input id="be_oldplan" placeholder="Ej.: Pack Vive Residencial"></div>
      <div class="field"><label>Plan nuevo (opcional)</label><input id="be_newplan" placeholder="Ej.: TV Hogar HD + Mega 500"></div>
      <div class="field"><label>Fecha del cambio (opcional)</label><input id="be_change" placeholder="Ej.: 1 de abril"></div>
      <div class="field"><label>DOM (opcional)</label><input id="be_dom" placeholder="Ej.: 9"></div>`;
  } else if(service==='fixed' && cause==='discount'){
    extra=`
      <div class="field full"><label>Descuento identificado (opcional)</label><input id="be_detail" placeholder="Ej.: Descuento de retención / promocional"></div>`;
  } else if(service==='fixed' && cause==='sva'){
    extra=`
      <div class="field"><label>Servicio adicional (opcional)</label><input id="be_detail" placeholder="Ej.: Extensor WiFi Mesh"></div>
      <div class="field"><label>Fecha de instalación (opcional)</label><input id="be_change" placeholder="Ej.: 8 de agosto"></div>`;
  } else if(service==='fixed' && cause==='assistance'){
    extra=`<div class="field full"><label>Periodo o detalle confirmado (opcional)</label><input id="be_detail" placeholder="Ej.: Asistencia VTR - periodo agosto"></div>`;
  } else if(service==='fixed' && cause==='ipc'){
    extra=`<div class="field full"><label>Detalle confirmado (opcional)</label><input id="be_detail" placeholder="Ej.: Servicios sin cambios; alza corresponde a IPC"></div>`;
  } else if(service==='fixed' && cause==='cut'){
    extra=`
      <div class="field"><label>Servicio</label><select id="be_detail"><option>Internet</option><option>Televisión</option></select></div>
      <div class="field"><label>Fecha de vencimiento (opcional)</label><input id="be_change" placeholder="Ej.: 10 de agosto"></div>`;
  } else if(service==='fixed' && cause==='premium'){
    extra=`<div class="field full"><label>Pack / canal identificado (opcional)</label><input id="be_detail" placeholder="Ej.: TNT Sports Premium"></div>`;
  } else if(service==='mobile' && cause==='rental'){
    extra=`
      <div class="field"><label>Equipo (opcional)</label><input id="be_detail" placeholder="Ej.: Motorola Moto E7"></div>
      <div class="field"><label>Cuota (opcional)</label><input id="be_change" placeholder="Ej.: cuota 4 de 18"></div>`;
  } else if(service==='mobile' && cause==='cut'){
    extra=`<div class="field full"><label>Fecha de vencimiento (opcional)</label><input id="be_change" placeholder="Ej.: 10 de agosto"></div>`;
  } else if(service==='mobile' && cause==='longdistance'){
    extra=`<div class="field full"><label>Periodo revisado (opcional)</label><input id="be_detail" placeholder="Ej.: consumo correspondiente a agosto"></div>`;
  } else if(service==='mobile' && cause==='proportional'){
    extra=`
      <div class="field"><label>Plan anterior (opcional)</label><input id="be_oldplan" placeholder="Plan anterior"></div>
      <div class="field"><label>Plan nuevo (opcional)</label><input id="be_newplan" placeholder="Plan nuevo"></div>
      <div class="field full"><label>Fecha del cambio (opcional)</label><input id="be_change" placeholder="Ej.: 15 de agosto"></div>`;
  } else if(service==='mobile' && cause==='noservice'){
    extra=`
      <div class="field"><label>Días considerados (opcional)</label><input id="be_change" placeholder="Ej.: 2 días"></div>
      <div class="field"><label>Monto del descuento (opcional)</label><input id="be_detail" placeholder="Ej.: $664"></div>`;
  } else if(service==='mobile' && cause==='additional'){
    extra=`<div class="field full"><label>Servicio adicional identificado</label><input id="be_detail" placeholder="Ej.: Simcard / bolsa de navegación"></div>`;
  } else if(service==='mobile' && cause==='minutes'){
    extra=`<div class="field full"><label>Detalle de consumo (opcional)</label><input id="be_detail" placeholder="Ej.: llamadas a móviles - 333:10 min"></div>`;
  }
  box.innerHTML=extra;
}
function billingCauseExplanation(service,cause,d){
  const detail=d.detail, change=d.change, dom=d.dom, oldplan=d.oldplan, newplan=d.newplan;
  if(service==='fixed'){
    if(cause==='promo'){
      let s='la actualización de su promoción realizada dentro del ciclo de facturación';
      let ext='Al hacerse el cambio dentro del ciclo, la boleta puede reflejar por única vez días proporcionales del nuevo plan y el ajuste de los días no utilizados del plan anterior';
      if(change) ext+=` desde el ${change}`;
      if(dom) ext+=` considerando su DOM ${dom}`;
      if(oldplan || newplan){
        const parts=[];
        if(oldplan) parts.push(`plan anterior: ${oldplan}`);
        if(newplan) parts.push(`plan nuevo: ${newplan}`);
        ext+=`. En la revisión identificamos `+parts.join(' y ');
      }
      return {cause:s, detail:ext+'.'};
    }
    if(cause==='discount'){
      return {cause:'el término o eliminación de un descuento que aparecía en la boleta anterior',
              detail:(detail?`El descuento identificado es ${detail}. `:'')+'Por eso el total actual puede verse más alto aunque los servicios principales se mantengan.'};
    }
    if(cause==='sva'){
      return {cause:'un servicio adicional incorporado a la cuenta',
              detail:`${detail?`El servicio identificado es ${detail}. `:''}${change?`La instalación se realizó el ${change}. `:''}Este tipo de cobro puede incluir el proporcional desde la instalación y la renta del periodo, según lo reflejado en la boleta.`};
    }
    if(cause==='assistance'){
      return {cause:'el cobro de Asistencia VTR registrado en Otros Cargos',
              detail:`${detail?detail+'. ':''}Según el procedimiento, este concepto puede tener proporcionales y estar sujeto a reajuste de IPC cuando corresponda.`};
    }
    if(cause==='ipc'){
      return {cause:'un reajuste por IPC',
              detail:`${detail?detail+'. ':''}El procedimiento indica revisar este escenario especialmente en enero y julio y confirmar que no existan otros cambios que expliquen la diferencia.`};
    }
    if(cause==='cut'){
      return {cause:`un cargo de corte y reposición del servicio${detail?` de ${detail}`:''}`,
              detail:`${change?`La fecha de vencimiento revisada fue ${change}. `:''}Este concepto se genera cuando corresponde la reposición del servicio después del vencimiento, de acuerdo con las condiciones del procedimiento.`};
    }
    if(cause==='premium'){
      return {cause:'un canal o pack Premium asociado a la cuenta',
              detail:`${detail?`El concepto identificado es ${detail}. `:''}Este cobro se visualiza dentro de Consumos y Servicios Adicionales y puede incluir ajustes proporcionales cuando corresponda.`};
    }
  } else {
    if(cause==='rental'){
      return {cause:'la cuota del equipo en arriendo',
              detail:`${detail?`El equipo identificado es ${detail}. `:''}${change?`La boleta muestra ${change}. `:''}El procedimiento permite revisar el valor mensual y el avance de las cuotas del equipo.`};
    }
    if(cause==='cut'){
      return {cause:'un cargo de corte y reposición del servicio móvil',
              detail:`${change?`La fecha de vencimiento revisada fue ${change}. `:''}El procedimiento indica validar este cobro cuando corresponde la reposición posterior al vencimiento.`};
    }
    if(cause==='longdistance'){
      return {cause:'consumos de larga distancia',
              detail:`${detail?detail+'. ':''}El monto debe revisarse en la sección de Comunicaciones a larga distancia de la boleta.`};
    }
    if(cause==='proportional'){
      let ext='El proporcional se relaciona con un cambio de promoción realizado dentro del periodo';
      if(change) ext+=` el ${change}`;
      if(oldplan || newplan){
        const parts=[];
        if(oldplan) parts.push(`plan anterior ${oldplan}`);
        if(newplan) parts.push(`plan nuevo ${newplan}`);
        ext+=`; se revisó `+parts.join(' y ');
      }
      return {cause:'un cobro proporcional por cambio de plan o promoción', detail:ext+'.'};
    }
    if(cause==='noservice'){
      return {cause:'el ajuste por días sin servicio reflejado como descuento',
              detail:`${change?`Se consideraron ${change}. `:''}${detail?`El descuento identificado es ${detail}. `:''}En la boleta este ajuste puede aparecer como “Descuento: Ley de telecom.”.`};
    }
    if(cause==='additional'){
      return {cause:'un servicio adicional asociado a la línea móvil',
              detail:`${detail?`El concepto identificado es ${detail}. `:''}El procedimiento indica revisar el detalle de cobros y los pedidos previos para confirmar su origen.`};
    }
    if(cause==='minutes'){
      return {cause:'el consumo de minutos del periodo',
              detail:`${detail?`El detalle revisado es ${detail}. `:''}La boleta permite revisar el consumo por tipo de llamada y Andes entrega el detalle disponible del periodo.`};
    }
  }
  return {cause:'el concepto identificado en la revisión de la boleta', detail:''};
}
function billingExplainer(selectedCause='', selectedService='fixed'){
  const service=selectedService==='mobile'?'mobile':'fixed';
  const causes=billingExplainerCauses[service];
  const cause=causes.some(x=>x.id===selectedCause)?selectedCause:causes[0].id;

  render(`
    <div class="breadcrumb">Boleta / Explicador automático</div>
    
    <div class="question">Construye una explicación clara para el cliente</div>
    <div class="instruction">
      Completa los datos que ya validaste en la boleta o en Billing Compare. La herramienta calculará la diferencia y preparará una versión breve y una detallada.
    </div>

    ${speechBox('Entiendo que quiera tener claridad sobre el monto de su boleta. Voy a comparar los periodos y revisar el concepto que genera la diferencia para explicárselo de forma simple.','Inicio de la conversación')}

    <div class="form-grid">
      <div class="field">
        <label>Tipo de boleta</label>
        <select id="be_service" data-change="updateBillingCauseOptions()">
          <option value="fixed" ${service==='fixed'?'selected':''}>Servicios fijos</option>
          <option value="mobile" ${service==='mobile'?'selected':''}>Servicios móviles</option>
        </select>
      </div>
      <div class="field">
        <label>Causa identificada</label>
        <select id="be_cause" data-change="updateBillingExtraFields()">
          ${causes.map(x=>`<option value="${x.id}" ${x.id===cause?'selected':''}>${x.label}</option>`).join('')}
        </select>
      </div>

      <div class="field">
        <label>Monto boleta anterior</label>
        <input id="be_previous" inputmode="numeric" placeholder="Ej.: 35.790">
      </div>
      <div class="field">
        <label>Monto boleta actual</label>
        <input id="be_current" inputmode="numeric" placeholder="Ej.: 49.280">
      </div>

      <div class="field">
        <label>Periodo anterior (opcional)</label>
        <input id="be_prev_period" placeholder="Ej.: diciembre 2025">
      </div>
      <div class="field">
        <label>Periodo actual (opcional)</label>
        <input id="be_current_period" placeholder="Ej.: enero 2026">
      </div>

      <div id="be_extra_fields" class="form-grid field full" style="margin:0;"></div>

      <div class="field full">
        <label>Dato adicional confirmado (opcional) <span class="helper-inline">(Solo agrega información que hayas verificado durante la gestión.)</span></label>
        <textarea id="be_note" placeholder="Ej.: el cliente realizó el cambio el 1 de abril; se validó en Pedidos / Billing Compare."></textarea>
      </div>
    </div>

    <label class="validation-check">
      <input type="checkbox" id="be_validated">
      <span><b>Confirmo que ya identifiqué esta causa en la boleta / Billing Compare / sistema correspondiente.</b><br>
      El generador ayuda a explicarla; no reemplaza la validación del procedimiento.</span>
    </label>

    <div class="generator-actions">
      <button class="btn btn-primary" data-click="generateBillingExplanation()">✨ Generar explicación</button>
      <button class="btn btn-secondary" data-click="clearBillingExplainer()">Limpiar</button>
    </div>

    <div id="be_output"></div>
    ${footer()}
  `);
  updateBillingExtraFields();
}
function clearBillingExplainer(){
  ['be_previous','be_current','be_prev_period','be_current_period','be_note'].forEach(id=>{
    const el=document.getElementById(id); if(el) el.value='';
  });
  const c=document.getElementById('be_validated'); if(c) c.checked=false;
  updateBillingExtraFields();
  const out=document.getElementById('be_output'); if(out) out.innerHTML='';
}
function generateBillingExplanation(){
  const validated=document.getElementById('be_validated')?.checked;
  const out=document.getElementById('be_output');
  if(!validated){
    out.innerHTML=`<div class="action-box danger"><b>Antes de generar</b>Confirma que ya identificaste la causa en la boleta, Billing Compare o el sistema correspondiente.</div>`;
    return;
  }

  const service=val('be_service') || 'fixed';
  const cause=val('be_cause');
  const prev=parseCLP(val('be_previous'));
  const curr=parseCLP(val('be_current'));
  const prevPeriod=val('be_prev_period');
  const currPeriod=val('be_current_period');
  const note=val('be_note');
  const data={
    detail:val('be_detail'),
    change:val('be_change'),
    dom:val('be_dom'),
    oldplan:val('be_oldplan'),
    newplan:val('be_newplan')
  };
  const info=billingCauseExplanation(service,cause,data);

  let diff=null, movement='', metric='';
  if(prev!==null && curr!==null){
    diff=curr-prev;
    if(diff>0) movement=`subió ${formatCLP(diff)}`;
    else if(diff<0) movement=`disminuyó ${formatCLP(Math.abs(diff))}`;
    else movement='se mantiene sin diferencia';
    metric=`
      <div class="metric-strip">
        <div class="metric-mini"><span>Boleta anterior</span><strong>${formatCLP(prev)}</strong></div>
        <div class="metric-mini"><span>Boleta actual</span><strong>${formatCLP(curr)}</strong></div>
        <div class="metric-mini"><span>Diferencia</span><strong>${diff===0?'$0':(diff>0?'+':'-')+formatCLP(Math.abs(diff))}</strong></div>
      </div>`;
  }

  const periodText=(prevPeriod||currPeriod)
    ? `Comparé ${prevPeriod?`la boleta de ${prevPeriod}`:'el periodo anterior'} con ${currPeriod?`la de ${currPeriod}`:'el periodo actual'}. `
    : '';

  const moneyText=(prev!==null && curr!==null)
    ? `El monto pasó de ${formatCLP(prev)} a ${formatCLP(curr)}, por lo que ${movement}. `
    : '';

  const brief =
    `Entiendo que este monto le genere dudas. ${periodText}${moneyText}` +
    `La diferencia se relaciona con ${info.cause}. ` +
    `${info.detail} ` +
    `Si le parece, revisamos juntos dónde aparece este concepto en su boleta para que quede claro.`;

  const detailed =
    `Entiendo que quiera tener claridad sobre el cobro y por eso revisé el detalle antes de explicárselo. ` +
    `${periodText}${moneyText}` +
    `Lo que identificamos es ${info.cause}. ${info.detail}` +
    `${note?` Además, en la revisión confirmé lo siguiente: ${note}.`:''} ` +
    `Por eso este periodo puede verse distinto al anterior. Antes de finalizar, quiero asegurarme de que quede claro qué cambió, desde cuándo y cómo impactó el total de su boleta.`;

  const close =
    `¿Le quedó claro de dónde proviene la diferencia? Si hay otro concepto de la boleta que le genere dudas, lo revisamos ahora.`;

  out.innerHTML=`
    ${metric}
    <div class="generated-wrap">
      <div class="generated-card">
        <div class="generated-head"><span>⚡ Versión breve</span><button class="btn btn-secondary" data-click="copyGenerated('be_short')">Copiar</button></div>
        <div class="generated-text" id="be_short"></div>
      </div>
      <div class="generated-card">
        <div class="generated-head"><span>💬 Versión detallada</span><button class="btn btn-secondary" data-click="copyGenerated('be_long')">Copiar</button></div>
        <div class="generated-text" id="be_long"></div>
      </div>
      <div class="generated-card">
        <div class="generated-head"><span>✅ Cierre de comprensión</span><button class="btn btn-secondary" data-click="copyGenerated('be_close')">Copiar</button></div>
        <div class="generated-text" id="be_close"></div>
      </div>
    </div>
    <div class="action-box warning"><b>Uso recomendado</b>No leas el texto de forma robótica. Úsalo como guía, mantén un tono conversacional y evita afirmar que un cobro es correcto si el cliente aún lo desconoce o si falta completar la validación de excepciones.</div>
  `;
  document.getElementById('be_short').textContent=brief.replace(/\s+/g,' ').trim();
  document.getElementById('be_long').textContent=detailed.replace(/\s+/g,' ').trim();
  document.getElementById('be_close').textContent=close;
}
function copyGenerated(id){
  const text=document.getElementById(id)?.textContent || '';
  if(text) copyText(text);
}


