// ---------- integración con React ----------
let currentHtml = '';
let htmlNotifier = null;
export function setRenderNotifier(fn){ htmlNotifier = fn; }
export function setToastNotifier(fn){ toastNotifier = fn; }
export function getHtml(){ return currentHtml; }

function scrollTop(){
  const c = document.querySelector('.asistente-pasos');
  if(c){
    let p = c.parentElement;
    while(p){
      if(p.scrollHeight > p.clientHeight && (p.scrollHeight - p.clientHeight) > 10){
        const o = getComputedStyle(p).overflowY;
        if(o === 'auto' || o === 'scroll' || o === 'overlay'){ p.scrollTo({top:0,behavior:'smooth'}); return; }
      }
      p = p.parentElement;
    }
  }
  window.scrollTo({top:0,behavior:'smooth'});
}

function splitTopLevel(s){
  const out=[]; let cur='', q=null;
  for(let i=0;i<s.length;i++){
    const ch=s[i];
    if(q){ cur+=ch; if(ch===q) q=null; continue; }
    if(ch==="'"||ch==='"'){ q=ch; cur+=ch; continue; }
    if(ch===','){ out.push(cur.trim()); cur=''; continue; }
    cur+=ch;
  }
  if(cur.trim()!=='') out.push(cur.trim());
  return out;
}

function evalLiteral(s){
  if(/^[A-Za-z_$][\w$]*$/.test(s)) return s;
  return new Function('return ('+s+')')();
}

function run(code, el){
  if(!code) return;
  if(code==='back()') return back();
  if(code==='goHome()') return goHome();
  if(code==='copy-from-code'){
    const box=el && el.closest && el.closest('.copyline');
    const cnode=box && box.querySelector('code');
    if(cnode) copyText(cnode.textContent);
    return;
  }
  const i=code.indexOf('(');
  if(i<0) return;
  const fnName=code.slice(0,i).trim();
  const inner=code.slice(i+1, code.lastIndexOf(')'));
  const fn=registry[fnName];
  if(typeof fn!=='function') return;
  if(fnName==='filterTvCases'){
    return fn((el && el.value) || '');
  }
  if(fnName==='nav'){
    const parts=splitTopLevel(inner);
    if(parts.length>0){
      const target=parts.shift();
      const targetFn=registry[target];
      if(typeof targetFn==='function'){
        const args=parts.map(evalLiteral);
        push({fn:targetFn,args});
        targetFn(...args);
      }
    }
    return;
  }
  const args=inner.trim()!=='' ? splitTopLevel(inner).map(evalLiteral) : [];
  fn(...args);
}

export function handleClick(e){
  const t = e.target instanceof Element ? e.target : null;
  if(!t) return;
  const el=t.closest('[data-click]');
  if(el) run(el.getAttribute('data-click'), el);
}
export function handleChange(e){
  const t = e.target instanceof Element ? e.target : null;
  if(!t) return;
  const el=t.closest('[data-change]');
  if(el) run(el.getAttribute('data-change'), el);
}
export function handleInput(e){
  const t = e.target instanceof Element ? e.target : null;
  if(!t) return;
  const el=t.closest('[data-input]');
  if(el) run(el.getAttribute('data-input'), el);
}
export function init(){ goHome(); }
